CREATE TABLE account_deletions(tenant_id TEXT PRIMARY KEY REFERENCES tenants(id),state TEXT NOT NULL CHECK(state IN ('pending','completed')),requested_at INTEGER NOT NULL);
CREATE TABLE catalog_item_assets(tenant_id TEXT NOT NULL,item_id TEXT NOT NULL,asset_id TEXT NOT NULL,PRIMARY KEY(tenant_id,item_id),FOREIGN KEY(tenant_id,item_id) REFERENCES catalog_items(tenant_id,id),FOREIGN KEY(tenant_id,asset_id) REFERENCES merchant_assets(tenant_id,id));
ALTER TABLE setup_operations ADD COLUMN business_mode TEXT NOT NULL DEFAULT 'appointments';
CREATE TRIGGER setup_mode_guard BEFORE INSERT ON setup_operations BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND business_mode=NEW.business_mode) THEN RAISE(ABORT,'mode_has_activity') END; END;
DROP TRIGGER retention_guard;
CREATE TRIGGER retention_guard BEFORE INSERT ON retention_guards BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM customers c JOIN tenants t ON t.id=c.tenant_id WHERE c.id=NEW.customer_id AND c.tenant_id=NEW.tenant_id AND t.retention_days>0 AND c.phone NOT LIKE 'deleted:%' AND MAX(c.created_at,COALESCE((SELECT MAX(b.ends_at) FROM bookings b WHERE b.tenant_id=c.tenant_id AND b.customer_id=c.id),0),COALESCE((SELECT MAX(MAX(i.created_at,COALESCE(i.fulfilled_at,0))) FROM inquiries i WHERE i.tenant_id=c.tenant_id AND i.customer_id=c.id),0))<NEW.checked_at-t.retention_days*86400000) THEN RAISE(ABORT,'customer_recently_active') END; END;
CREATE TRIGGER fulfilled_event AFTER UPDATE OF status ON inquiries WHEN NEW.status='fulfilled' AND OLD.status!='fulfilled' BEGIN INSERT OR IGNORE INTO launch_events VALUES ('fulfilled:'||NEW.id,NEW.tenant_id,'fulfillment_completed','fulfilled:'||NEW.id,NEW.fulfilled_at); END;
